114: export async function checkSolverProof(problem: SolverProblem, worktree: string, env: NodeJS.ProcessEnv,
115:   signal?: AbortSignal, previous?: ProofCheck, timeoutMs = 180_000): Promise<ProofCheck> {
116:   signal?.throwIfAborted();
117:   const commit = commitSolverSources(problem, worktree);
118:   const projectRoot = path.join(worktree, problem.projectRelative);
119:   const sourceDigest = solverSourceDigest(problem, worktree);
120:   const environment = proofReuseEnvironment(projectRoot, env);
121:   const inputDigest = environment.reusable ? mathDigest(canonicalMathJson({
122:     tree: git(worktree, ['ls-tree', '-r', '-z', '--full-tree', 'HEAD']).split('\0')
123:       .filter(entry => entry && entry.slice(entry.indexOf('\t') + 1) !== 'RESEARCH.md'),
124:     problem: problem.receiptDigest, kind: problem.kind, project: problem.projectRelative,
125:     targets: problem.targets, statement: problem.contract.statementHash, leanStatement: problem.contract.leanStatementHash,
126:     sourceDigest, environment: environment.digest,
127:   })) : undefined;
128:   const provenance = previous && checkedRejections.get(previous);
129:   if (inputDigest && provenance?.inputDigest === inputDigest && previous && !previous.passed &&
130:       previous.sourceDigest === sourceDigest && provenance.verificationDigest === proofVerificationDigest(previous.verification)) {
131:     const reused = previous.commit === commit ? previous : { ...previous, commit };
132:     checkedRejections.set(reused, provenance);
133:     return reused;
134:   }
135:   const evidence = await checkProofEvidence({ projectRoot, targetCommit: commit, timeoutMs,
136:     items: problem.targets.map(target => ({ proofPath: target.proofPath, theoremName: target.theoremName,
137:       expectedSourceDeclarationHash: target.declarationHash, statementHash: problem.contract.statementHash,
138:       leanStatementHash: problem.contract.leanStatementHash, claim: 'statement' as const })) },
139:   { env: environment.env, signal, prepareLocalDependencies: problem.kind === 'lean-eval', collectDeclarationReferences: true });
140:   const check = { commit, sourceDigest, ...evidence };
141:   if (check.passed) checkedProofs.set(check, proofIdentity(check));
142:   if (!check.passed && inputDigest && hasDeterministicLeanFailure(check.verification) &&
143:       proofReuseEnvironment(projectRoot, environment.env).digest === environment.digest)
144:     checkedRejections.set(check, { inputDigest, verificationDigest: proofVerificationDigest(check.verification) });
145:   return check;
146: }
